//! Types and pure helpers shared by native Rust tests and CLVM compilation.
//!
//! Nominal types prevent source-level domain swaps. Their public constructors
//! establish no cryptographic or protocol invariant. The CLVM ABI validates the
//! inner representation, not a runtime nominal tag or constructor predicate.
#![no_std]

pub use chialisp_oxide_macros::puzzle;

mod domain;
pub use domain::*;

mod tree;
pub use tree::*;

//! Immutable CLVM data, with ordinary Rust lifetimes and pattern matching.
//!
//! A tree carries its original atom bytes. Numeric padding, improper pairs and
//! arbitrary tails are data; this type does not interpret or normalize them.
//! The compiler supports direct recursive traversal of this restricted shape.
//! General enums, mutable references, allocating output trees, and general
//! runtime program evaluation remain outside the supported subset.

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Tree<'a> {
    Atom(&'a [u8]),
    Pair(&'a Tree<'a>, &'a Tree<'a>),
}

/// CLVM's quote operator as data, for constructing a quoted program.
pub const QUOTE: Tree<'static> = Tree::Atom(&[1]);

/// Construct a program returning `value` when applied to any environment.
///
/// This is an ordinary Rust function. The compiler checks and lowers its MIR;
/// its name does not grant it intrinsic semantics.
pub fn quote<'a>(value: &'a Tree<'a>) -> Tree<'a> {
    Tree::Pair(&QUOTE, value)
}

